#!/bin/sh
# Generate cordis.dev.yml with the absolute single-row bundle path for `dsh web --patch`.
# Usage: sh scripts/gen-dev-overlay.sh   (run from dsh-plugin-stc/)
set -eu
ROOT=$(cd "$(dirname "$0")/.." && pwd)
cat > "$ROOT/cordis.dev.yml" <<EOF
# GENERATED by scripts/gen-dev-overlay.sh — do not commit, do not hand-edit.
# Single row on purpose: DSH's client-modules registry rejects multiple
# active loader sources for one package (startup fails). Dev loads the TS
# source directly (type-stripped; allowed outside node_modules); packaged
# installs load the built lib/index.js instead (see cordis.bundle.yml).
- insert:
    - id: stc-bundle
      name: '$ROOT/src/index.ts'
EOF
echo "wrote $ROOT/cordis.dev.yml"
